package dev.slithergoh.pixelmonradar.client.screen;
import dev.slithergoh.pixelmonradar.client.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.EditBox;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import java.util.*;
public final class RadarScreen extends Screen{
 private enum Page{RADAR,FILTERS,COLLECTION,SETTINGS}private Page page=Page.RADAR;private EditBox search;private List<PokemonInfo>visible=List.of();private int x,y,w,h,scroll;private int inspected=-1;private int settingsScroll=0;private long opened,changed;
 public RadarScreen(){super(Component.literal("Atlas"));}
 @Override protected void init(){w=Math.min(560,Math.max(300,width-24));h=Math.min(390,Math.max(220,height-24));x=(width-w)/2;y=(height-h)/2;opened=changed=System.currentTimeMillis();search=new EditBox(font,x+20,y+52,190,20,Component.literal("Search"));search.setBordered(false);search.setHint(Component.literal("Search Pokemon..."));search.setValue(RadarSettings.search);search.setResponder(s->{RadarSettings.search=s.trim();scroll=0;});addRenderableWidget(search);}
 private void data(){ArrayList<PokemonInfo>a=new ArrayList<>(PokemonScanner.scan());String q=RadarSettings.search.toLowerCase();if(!q.isBlank())a.removeIf(p->!p.name().toLowerCase().contains(q));Comparator<PokemonInfo>c=switch(RadarSettings.sortMode){case LEVEL->Comparator.comparingInt(PokemonInfo::level).reversed();case NAME->Comparator.comparing(PokemonInfo::name,String.CASE_INSENSITIVE_ORDER);case RARITY->Comparator.comparingInt(this::pri).reversed().thenComparingDouble(PokemonInfo::distance);default->Comparator.comparingDouble(PokemonInfo::distance);};a.sort(c);visible=a;}
 @Override public void renderBackground(GuiGraphics g,int mx,int my,float pt){}
 @Override public void render(GuiGraphics g,int mx,int my,float pt){data();float a=ease(Math.min(1f,(System.currentTimeMillis()-opened)/220f));int yy=y+(int)((1-a)*12);g.pose().pushPose();g.pose().translate(0,yy-y,0);round(g,x,yy-(yy-y),x+w,y+h,12,0xF4080E14);round(g,x+1,y+1,x+w-1,y+42,11,0xFF101C25);g.fill(x+1,y+34,x+w-1,y+43,0xFF101C25);g.drawString(font,"ATLAS",x+18,y+16,0xFFF5FAFC,true);g.drawString(font,"POKEMON RADAR",x+60,y+16,0xFF66C9EF,false);nav(g,x+w-310,y+11,66,"RADAR",page==Page.RADAR);nav(g,x+w-240,y+11,66,"FILTER",page==Page.FILTERS);nav(g,x+w-170,y+11,82,"DEX",page==Page.COLLECTION);nav(g,x+w-84,y+11,70,"SETTINGS",page==Page.SETTINGS);g.pose().popPose();
  round(g,x+14,y+48,x+220,y+76,8,0xFF111D25);g.drawString(font,"SEARCH",x+22,y+58,0xFF6AC9EC,false);search.setX(x+67);search.setY(y+55);search.setWidth(140);super.render(g,mx,my,pt);
  float t=ease(Math.min(1f,(System.currentTimeMillis()-changed)/160f));g.pose().pushPose();g.pose().translate((1-t)*9,0,0);if(page==Page.RADAR)radar(g,mx,my);else if(page==Page.FILTERS)filters(g);else if(page==Page.COLLECTION)collection(g);else settings(g);g.pose().popPose();g.drawString(font,visible.size()+" nearby",x+18,y+h-17,0xFF718A96,false);g.drawString(font,"R to close",x+w-62,y+h-17,0xFF718A96,false);}
 private void radar(GuiGraphics g,int mx,int my){int lx=x+24,top=y+94;int panelW=Math.min(210,(w-60)/2);round(g,lx,top,lx+panelW,y+h-34,9,0xFF111D25);g.drawString(font,"MAP RADAR",lx+12,top+13,0xFF66C9EF,true);g.drawString(font,"JourneyMap integration",lx+12,top+32,0xFF91A7B2,false);int rare=0,needed=0;for(PokemonInfo p:visible){if(p.rare())rare++;if(!p.dexCaught())needed++;}g.drawString(font,visible.size()+" nearby",lx+12,top+57,0xFFE8F3F7,true);g.drawString(font,rare+" rare",lx+12,top+75,0xFFFFB64F,false);g.drawString(font,needed+" uncaught",lx+12,top+92,0xFF62D7FF,false);g.drawString(font,"Use FILTER to refine",lx+12,top+125,0xFF8299A4,false);g.drawString(font,"map markers.",lx+12,top+139,0xFF8299A4,false);int rx=lx+panelW+12,right=x+w-20;g.drawString(font,"NEARBY",rx,top+2,0xFF8FA8B4,false);int max=Math.max(0,Math.min(visible.size(),(h-145)/43));for(int i=0;i<max;i++){PokemonInfo p=visible.get(i);int yy=top+20+i*43;boolean tr=p.entityId()==RadarSettings.trackedEntityId;round(g,rx,yy,right,yy+37,7,tr?0xFF21483E:0xFF111D25);if(p.sprite()!=null)g.blit(p.sprite(),rx+5,yy+5,0,0,26,26,26,26);int avail=Math.max(20,right-rx-45);String n=font.plainSubstrByWidth(p.name(),avail);g.drawString(font,n,rx+36,yy+5,p.rare()?accent(p):0xFFF1F5F7,true);g.drawString(font,"Lv."+p.level()+"  "+Math.round(p.distance())+"m",rx+36,yy+19,0xFF91A7B2,false);}} private void inspector(GuiGraphics g,PokemonInfo p){int lx=x+278,top=y+82;round(g,lx,top,x+w-16,y+h-28,10,0xFF111D25);if(p.sprite()!=null)g.blit(p.sprite(),lx+12,top+12,0,0,48,48,48,48);g.drawString(font,p.name(),lx+70,top+15,p.rare()?accent(p):0xFFFFFFFF,true);g.drawString(font,"Lv."+p.level()+"  "+dexLabel(p),lx+70,top+30,dexColor(p),false);g.drawString(font,Math.round(p.distance())+"m "+dir(p)+"  •  "+p.pos().getX()+", "+p.pos().getY()+", "+p.pos().getZ(),lx+14,top+72,0xFF91A7B2,false);g.drawString(font,"Gender  "+p.gender(),lx+14,top+91,0xFFD6E1E6,false);g.drawString(font,"Form  "+clean(p.form())+"   Palette  "+clean(p.palette()),lx+14,top+106,0xFFD6E1E6,false);String tags=p.badges().trim();if(tags.isBlank())tags="STANDARD";g.drawString(font,tags,lx+14,top+125,p.rare()?accent(p):0xFF718995,false);if(p.boss()&&!p.bossTier().isBlank())g.drawString(font,"Boss tier  "+p.bossTier(),lx+14,top+140,0xFFFF7777,false);boolean tr=p.entityId()==RadarSettings.trackedEntityId;pill(g,lx+14,top+166,104,tr?"UNTRACK":"TRACK",tr);pill(g,lx+126,top+166,86,"BACK",false);}private String clean(String s){return s==null||s.isBlank()?"Default":s;}private void filters(GuiGraphics g){int yy=y+96;title(g,"SHOW ONLY",yy);yy+=20;filterChip(g,x+24,yy,118,"SHINY",RadarSettings.shinyOnly,0xFF62FFFF);filterChip(g,x+148,yy,118,"LEGENDARY",RadarSettings.filterLegendary,0xFFFFB64F);filterChip(g,x+272,yy,118,"MYTHICAL",RadarSettings.filterMythical,0xFFFFD477);filterChip(g,x+396,yy,118,"RARE +",RadarSettings.rareOnly,0xFFFF8D6A);yy+=34;filterChip(g,x+24,yy,118,"UB",RadarSettings.filterUltraBeast,0xFFB987FF);filterChip(g,x+148,yy,118,"PARADOX",RadarSettings.filterParadox,0xFFC493FF);filterChip(g,x+272,yy,118,"BOSS",RadarSettings.filterBoss,0xFFFF6666);yy+=36;filterChip(g,x+24,yy,180,"NOT CAUGHT",RadarSettings.uncaughtOnly,0xFFFFC85C);filterChip(g,x+212,yy,180,"NOT SEEN",RadarSettings.unseenOnly,0xFF62D7FF);yy+=38;g.drawString(font,"Enabled rarity filters combine as OR.",x+24,yy,0xFF718995,false);yy+=31;title(g,"SORT RESULTS",yy);yy+=20;int xx=x+24;for(RadarSettings.SortMode m:RadarSettings.SortMode.values()){int ww=font.width(m.name())+24;pill(g,xx,yy,ww,m.name(),RadarSettings.sortMode==m);xx+=ww+8;}}
 private void collection(GuiGraphics g){int yy=y+96;title(g,"POKEDEX OVERVIEW",yy);try{var dex=((com.pixelmonmod.pixelmon.api.extensions.PixelmonPlayerExtension)minecraft.player).getPokedexNow();if(dex==null){g.drawString(font,"Pokedex data is still syncing.",x+24,yy+28,0xFF8299A4,false);return;}int seen=dex.countSeen(),caught=dex.countCaught();round(g,x+24,yy+22,x+250,yy+92,10,0xFF111D25);g.drawString(font,"CAUGHT",x+39,yy+36,0xFF72D99A,false);g.drawString(font,String.valueOf(caught),x+39,yy+54,0xFFFFFFFF,true);round(g,x+266,yy+22,x+w-24,yy+92,10,0xFF111D25);g.drawString(font,"SEEN",x+281,yy+36,0xFFFFC85C,false);g.drawString(font,String.valueOf(seen),x+281,yy+54,0xFFFFFFFF,true);yy+=112;title(g,"NEARBY COLLECTION OPPORTUNITIES",yy);yy+=20;int n=0;for(PokemonInfo p:visible){if(p.dexCaught())continue;int cy=yy+n*38;if(n++>=4)break;round(g,x+24,cy,x+w-24,cy+32,7,0xFF111D25);if(p.sprite()!=null)g.blit(p.sprite(),x+31,cy+4,0,0,24,24,24,24);g.drawString(font,p.name(),x+62,cy+7,p.dexSeen()?0xFFFFC85C:0xFF62D7FF,true);g.drawString(font,(p.dexSeen()?"SEEN - NOT CAUGHT":"NEW DEX ENTRY")+"   "+Math.round(p.distance())+"m "+dir(p),x+62,cy+19,0xFF8299A4,false);}if(n==0)g.drawString(font,"No uncaught Pokemon are currently in radar range.",x+24,yy+10,0xFF718995,false);}catch(Exception ex){g.drawString(font,"Pokedex data unavailable.",x+24,yy+28,0xFF8299A4,false);}}private void settings(GuiGraphics g){int yy=y+98-settingsScroll;title(g,"RADAR EXPERIENCE",yy);yy+=25;setting(g,yy,"Compact HUD","Show Atlas while exploring",RadarSettings.hudEnabled);yy+=47;setting(g,yy,"Rare alerts","Notify you about important spawns",RadarSettings.alertsEnabled);yy+=47;setting(g,yy,"Alert sound","Play an audio cue for rare encounters",RadarSettings.alertSound);yy+=47;setting(g,yy,"Raid card","Show the best active nearby raid on the HUD",RadarSettings.raidHud);yy+=47;setting(g,yy,"Party status","Compact health and level overview while exploring",RadarSettings.partyHud);yy+=48;title(g,"DETECTION RANGE   "+RadarSettings.pokemonRange+"m",yy);yy+=22;slider(g,x+24,yy,w-48,(RadarSettings.pokemonRange-32)/224f);}
 private void cardToggle(GuiGraphics g,int yy,String n,String d,boolean on,int k){round(g,x+24,yy,x+w-24,yy+40,9,0xFF111D25);g.drawString(font,n,x+38,yy+9,on?0xFFF4F8FA:0xFFA4B1B7,true);g.drawString(font,d,x+38,yy+22,0xFF718995,false);toggle(g,x+w-76,yy+11,on);}
 private void setting(GuiGraphics g,int yy,String n,String d,boolean on){cardToggle(g,yy,n,d,on,0);}private void filterChip(GuiGraphics g,int xx,int yy,int ww,String s,boolean on,int col){round(g,xx,yy,xx+ww,yy+25,8,on?0xFF21404C:0xFF14232C);if(on)round(g,xx+7,yy+7,xx+10,yy+18,2,col);g.drawCenteredString(font,s,xx+ww/2,yy+8,on?0xFFF3FBFF:0xFF8298A3);}private void title(GuiGraphics g,String s,int yy){g.drawString(font,s,x+24,yy,0xFF8CA5B1,false);}
 private void nav(GuiGraphics g,int xx,int yy,int ww,String s,boolean on){round(g,xx,yy,xx+ww,yy+22,7,on?0xFF1D4254:0x00111111);g.drawCenteredString(font,s,xx+ww/2,yy+7,on?0xFFFFFFFF:0xFF78909C);if(on)round(g,xx+18,yy+20,xx+ww-18,yy+22,1,0xFF56C9F2);}
 private void pill(GuiGraphics g,int xx,int yy,int ww,String s,boolean on){round(g,xx,yy,xx+ww,yy+24,8,on?0xFF214B60:0xFF14232C);g.drawCenteredString(font,s,xx+ww/2,yy+8,on?0xFFFFFFFF:0xFF8298A3);}
 private void toggle(GuiGraphics g,int xx,int yy,boolean on){round(g,xx,yy,xx+42,yy+18,9,on?0xFF2A765E:0xFF2A3941);int k=on?xx+26:xx+3;round(g,k,yy+3,k+12,yy+15,6,on?0xFFA0FFD4:0xFF9BACB4);}
 private void slider(GuiGraphics g,int xx,int yy,int ww,float v){round(g,xx,yy,xx+ww,yy+6,3,0xFF243641);round(g,xx,yy,xx+(int)(ww*v),yy+6,3,0xFF4FC4ED);int k=xx+(int)(ww*v);round(g,k-5,yy-3,k+6,yy+10,6,0xFFE8F8FE);}
 private void ring(GuiGraphics g,int cx,int cy,int r,int c){for(int i=0;i<72;i++){double a=i*Math.PI*2/72;int xx=cx+(int)(Math.cos(a)*r),yy=cy+(int)(Math.sin(a)*r);g.fill(xx,yy,xx+1,yy+1,c);}}
 private String dexLabel(PokemonInfo p){return p.dexCaught()?"CAUGHT":p.dexSeen()?"SEEN":"NEW";}private int dexColor(PokemonInfo p){return p.dexCaught()?0xFF72D99A:p.dexSeen()?0xFFFFC85C:0xFF62D7FF;}private int pri(PokemonInfo p){if(p.shiny())return 100;if(p.legendary()||p.mythical())return 90;if(p.ultraBeast()||p.paradox())return 80;if(p.boss())return 70;return 0;}private int accent(PokemonInfo p){if(p.shiny())return 0xFF62FFFF;if(p.legendary()||p.mythical())return 0xFFFFB64F;if(p.ultraBeast()||p.paradox())return 0xFFB987FF;if(p.boss())return 0xFFFF6666;return 0xFF4FC4ED;}private String dir(PokemonInfo p){var mc=minecraft;double dx=p.pos().getX()+.5-mc.player.getX(),dz=p.pos().getZ()+.5-mc.player.getZ();double a=(Math.toDegrees(Math.atan2(-dx,dz))+360)%360;String[]d={"N","NE","E","SE","S","SW","W","NW"};return d[(int)Math.round(a/45)%8];}
 @Override public boolean mouseClicked(double mx,double my,int b){if(my>=y+11&&my<=y+33){if(mx>=x+w-310&&mx<x+w-244)return page(Page.RADAR);if(mx>=x+w-240&&mx<x+w-174)return page(Page.FILTERS);if(mx>=x+w-170&&mx<x+w-88)return page(Page.COLLECTION);if(mx>=x+w-84&&mx<x+w-14)return page(Page.SETTINGS);}if(page==Page.RADAR){int lx=x+24+Math.min(210,(w-60)/2)+12,top=y+114;for(int i=0;i<Math.min(visible.size(),Math.max(0,(h-145)/43));i++){int yy=top+i*43;if(mx>=lx&&mx<=x+w-16&&my>=yy&&my<=yy+39){int id=visible.get(i).entityId();RadarSettings.trackedEntityId=RadarSettings.trackedEntityId==id?-1:id;inspected=id;RadarSettings.save();return true;}}}if(false&&page==Page.RADAR&&inspected!=-1){int lx=x+278,top=y+82;if(my>=top+166&&my<=top+190){if(mx>=lx+14&&mx<=lx+118){RadarSettings.trackedEntityId=RadarSettings.trackedEntityId==inspected?-1:inspected;RadarSettings.save();return true;}if(mx>=lx+126&&mx<=lx+212){inspected=-1;return true;}}}else if(page==Page.FILTERS){int fy=y+116;if(my>=fy&&my<=fy+25){if(mx>=x+24&&mx<=x+142)RadarSettings.shinyOnly=!RadarSettings.shinyOnly;else if(mx>=x+148&&mx<=x+266)RadarSettings.filterLegendary=!RadarSettings.filterLegendary;else if(mx>=x+272&&mx<=x+390)RadarSettings.filterMythical=!RadarSettings.filterMythical;else if(mx>=x+396&&mx<=x+514)RadarSettings.rareOnly=!RadarSettings.rareOnly;else return super.mouseClicked(mx,my,b);RadarSettings.save();return true;}fy+=34;if(my>=fy&&my<=fy+25){if(mx>=x+24&&mx<=x+142)RadarSettings.filterUltraBeast=!RadarSettings.filterUltraBeast;else if(mx>=x+148&&mx<=x+266)RadarSettings.filterParadox=!RadarSettings.filterParadox;else if(mx>=x+272&&mx<=x+390)RadarSettings.filterBoss=!RadarSettings.filterBoss;else return super.mouseClicked(mx,my,b);RadarSettings.save();return true;}fy+=36;if(my>=fy&&my<=fy+25){if(mx>=x+24&&mx<=x+204)RadarSettings.uncaughtOnly=!RadarSettings.uncaughtOnly;else if(mx>=x+212&&mx<=x+392)RadarSettings.unseenOnly=!RadarSettings.unseenOnly;else return super.mouseClicked(mx,my,b);RadarSettings.save();return true;}int xx=x+24,yy=y+281;for(RadarSettings.SortMode m:RadarSettings.SortMode.values()){int ww=font.width(m.name())+24;if(mx>=xx&&mx<=xx+ww&&my>=yy&&my<=yy+24){RadarSettings.sortMode=m;RadarSettings.save();return true;}xx+=ww+8;}}else if(page==Page.SETTINGS){if(my>=y+123-settingsScroll&&my<=y+163-settingsScroll){RadarSettings.hudEnabled=!RadarSettings.hudEnabled;RadarSettings.save();return true;}if(my>=y+170-settingsScroll&&my<=y+210-settingsScroll){RadarSettings.alertsEnabled=!RadarSettings.alertsEnabled;RadarSettings.save();return true;}if(my>=y+217-settingsScroll&&my<=y+257-settingsScroll){RadarSettings.alertSound=!RadarSettings.alertSound;RadarSettings.save();return true;}if(my>=y+264-settingsScroll&&my<=y+304-settingsScroll){RadarSettings.raidHud=!RadarSettings.raidHud;RadarSettings.save();return true;}if(my>=y+311-settingsScroll&&my<=y+351-settingsScroll){RadarSettings.partyHud=!RadarSettings.partyHud;RadarSettings.save();return true;}int sy=y+381-settingsScroll;if(my>=sy-5&&my<=sy+15&&mx>=x+24&&mx<=x+w-24){double v=(mx-(x+24))/(double)(w-48);RadarSettings.pokemonRange=32+(int)Math.round(Math.max(0,Math.min(1,v))*7)*32;RadarSettings.save();return true;}}return super.mouseClicked(mx,my,b);}
 @Override public boolean mouseScrolled(double mx,double my,double dx,double dy){if(page==Page.SETTINGS){settingsScroll=Math.max(0,Math.min(180,settingsScroll-(int)Math.signum(dy)*35));return true;}return super.mouseScrolled(mx,my,dx,dy);}private boolean page(Page p){if(page!=p){page=p;changed=System.currentTimeMillis();}return true;}private static float ease(float t){return 1-(1-t)*(1-t)*(1-t);}private static void round(GuiGraphics g,int l,int t,int r,int b,int rad,int c){if(r<=l||b<=t)return;rad=Math.max(1,Math.min(rad,Math.min((r-l)/2,(b-t)/2)));g.fill(l+rad,t,r-rad,b,c);g.fill(l,t+rad,r,b-rad,c);for(int i=0;i<rad;i++){int in=(int)Math.ceil(rad-Math.sqrt(Math.max(0,rad*rad-(rad-i)*(rad-i))));g.fill(l+in,t+i,r-in,b-i,c);}}@Override public void onClose(){RadarSettings.save();super.onClose();}@Override public boolean isPauseScreen(){return false;}}
